function smallestLargestPile(piles: number[], maxSplits: number): number {
  let lo = 1, hi = 0;
  for (const p of piles) hi = Math.max(hi, p);
  while (lo < hi) {
    const mid = Math.floor((lo + hi) / 2);
    let need = 0;
    for (const p of piles) {
      need += Math.ceil(p / mid) - 1;
      if (need > maxSplits) break; // already too many
    }
    if (need <= maxSplits) hi = mid;
    else lo = mid + 1;
  }
  return lo;
}

