        lo, hi = 1, max(piles)
        while lo < hi:
            mid = (lo + hi) // 2
            need = sum((p - 1) // mid for p in piles)  # equals ceil(p / mid) - 1
            if need <= maxSplits:
                hi = mid
            else:
                lo = mid + 1
        return lo

